-- The running example `shop` (design record §1.3). The function bodies, which
-- the record elides as `$$ ... $$`, are minimal bodies returning numeric.

CREATE SCHEMA app;

CREATE DOMAIN app.email_address AS text
  CHECK (char_length(VALUE) <= 320);
CREATE DOMAIN app.slug_text AS text
  CHECK (VALUE ~ '^[a-z0-9]+(-[a-z0-9]+)*$');

CREATE TYPE app.post_status  AS ENUM ('draft', 'published', 'archived');
CREATE TYPE app.money_amount AS (amount numeric(12,2), currency char(3));

CREATE TABLE app.tenants (
  id   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL
);

CREATE TABLE app.users (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES app.tenants(id),
  email         app.email_address NOT NULL,
  display_name  varchar(80),
  password_hash text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1,
  CONSTRAINT users_tenant_email_key UNIQUE (tenant_id, email)
);

CREATE TABLE app.profiles (
  user_id  bigint PRIMARY KEY REFERENCES app.users(id),
  bio      text,
  birthday date
);

CREATE TABLE app.posts (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  author_id    bigint NOT NULL REFERENCES app.users(id),
  editor_id    bigint REFERENCES app.users(id),
  title        text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 200),
  slug         text GENERATED ALWAYS AS (lower(replace(title, ' ', '-'))) STORED,
  status       app.post_status NOT NULL DEFAULT 'draft',
  price        app.money_amount,
  labels       text[],
  published_at timestamptz,
  CONSTRAINT posts_published_check CHECK (published_at IS NULL OR status <> 'draft')
);

CREATE TABLE app.tags (
  id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name app.slug_text NOT NULL UNIQUE
);

CREATE TABLE app.post_tags (
  post_id bigint REFERENCES app.posts(id),
  tag_id  bigint REFERENCES app.tags(id),
  PRIMARY KEY (post_id, tag_id)
);

CREATE VIEW app.published_posts AS
  SELECT id, title, author_id, published_at
  FROM app.posts WHERE status = 'published';

CREATE FUNCTION app.post_score(p_id bigint) RETURNS numeric
  LANGUAGE sql STABLE STRICT AS $$ SELECT 0::numeric $$;
CREATE FUNCTION app.post_score(p_id bigint, window_days integer) RETURNS numeric
  LANGUAGE sql STABLE STRICT AS $$ SELECT 0::numeric $$;

-- Annotations: pg-live reads @-markers from comments (§7)
COMMENT ON COLUMN app.users.tenant_id      IS '@bound';
COMMENT ON COLUMN app.users.password_hash  IS '@write-only @sensitive';
COMMENT ON COLUMN app.users.created_at     IS '@immutable';
COMMENT ON COLUMN app.users.updated_at     IS '@db-updated';
COMMENT ON COLUMN app.users.version        IS '@version';
COMMENT ON VIEW   app.published_posts      IS '@logical-key(id)';
COMMENT ON COLUMN app.published_posts.id    IS '@nonnull';
COMMENT ON COLUMN app.published_posts.title IS '@nonnull';
COMMENT ON FUNCTION app.post_score(bigint)          IS '@public';
COMMENT ON FUNCTION app.post_score(bigint, integer) IS '@public';

-- Objects the record's other examples rely on. Neither changes anything §1.3
-- defines: the index adds a uniqueness fact (§11.2), and config still wins
-- over the comment, so the relation stays named `profile` (§4.5, §7.6).
CREATE UNIQUE INDEX posts_one_published_slug ON app.posts (slug) WHERE status = 'published';
COMMENT ON CONSTRAINT profiles_user_id_fkey ON app.profiles IS '@inverse-name(user_profile)';
